      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n8/20~25) 만30~40대 남녀(1977~1996년생) 차, 티백 관련 좌담회\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.08.10. 17:42\n조회 113\n구독\n8/20~25) 만30~40대 남녀(1977~1996년생) 차, 티백 관련 좌담회\n신청하신분은 재신청 안하셔도 됩니다\n공통 사항\n약 2시간 진행\n만 30~40대 남녀 (1977~1996년생)\n티백 형태의 차 ( 티백을 물에 우려 마시는 차)를 최근 1개월 기준 주 1-2회이상 드시는 분\n본인이 먹기 위해 티백 제품을 직접 선택하여 구입하는 사람\n티백 제품에 대한 관심과 관여도가 높고 음용 습관이나 티백차에 대한 응답을 다양하게 해주실분\n사례비 5만원 좌담회 참석후 일주일 내로 계좌이체 예정 (본인인증 필요)\n좌담회 일시 : 8월 20일 목 /21일 금/ 24일 월/ 25일 화\n16시 혹은 19시 30분 시작 ( 선정질문 후 그룹 선정에 따라 참석 날짜 시간이 정해집니다 )\n장소 : 경복궁역 인근\n신청시 작성 내용 : 이름 / 핸드폰 번호 / 나이(년생) /성별 / 현재거주지/ 직업(회사명 업종 부서)/일주일 총 몇회 티백 형태의 차를 음용하는지 (예 일주일 1-2회)/ 티백제품 최근 구입 언제?(예 최근3개월이내)/ 주로 드시는 태백 제품 브랜드 (브랜드 제품맛 정확하게) 예 동서 둥글레차 , 오설록 제주호지차 / 개인정보 동의여부\nhttps://forms.gle/fyXCpRsFZVqedJ4j9\n좋아요\n1\n좋아요한 사람 목록으로 이동\n송파구 이웃끼리 공유하는 동네 꿀정보\n댓글\n0\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n첫 댓글을 남겨보세요\n전체글\n고유링크)8/26~27)만16~19세 수도권거주 여성) 월 1회 이상 디저트 매장 이용자 좌담회\n좌담회알바좌담회카페\n26.08.10.\n댓글\n0\n8/20~25) 만30~40대 남녀(1977~1996년생) 차, 티백 관련 좌담회\n좌담회알바좌담회카페\n26.08.10.\n댓글\n0\n8/27) 만20~69세 암 경험이 있는 여성) 암 경험자 대상 좌담회\n좌담회알바좌담회카페\n26.08.10.\n댓글\n0\n8/27) 만20~69세 암 경험이 있는 남성) 암 경험자 대상 좌담회\n좌담회알바좌담회카페\n26.08.10.\n댓글\n0\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n1\n좋아요한 사람 목록으로 이동\n댓글\n0\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
